$ErrorActionPreference='Stop';$root=$PSScriptRoot
Import-Module (Join-Path $root 'src/GameState.psm1') -Force
Import-Module (Join-Path $root 'src/NarratorHandoff.psm1') -Force
Import-Module (Join-Path $root 'src/InterpreterContext.psm1') -Force
Import-Module (Join-Path $root 'src/IntentInterpreter.psm1') -Force
Import-Module (Join-Path $root 'src/IntentSchema.psm1') -Force
Import-Module (Join-Path $root 'src/CoreEngine.psm1') -Force
Import-Module (Join-Path $root 'src/NarrationPrompt.psm1') -Force
Import-Module (Join-Path $root 'src/NarrationPacket.psm1') -Force
Import-Module (Join-Path $root 'src/NarrationValidation.psm1') -Force
Import-Module (Join-Path $root 'src/CommaHarness.psm1') -Force
Import-Module (Join-Path $root 'src/InferenceService.psm1') -Force
# Dependency imports above can replace nested module instances; restore the public state commands in script scope.
Import-Module (Join-Path $root 'src/GameState.psm1') -Force
Import-Module (Join-Path $root 'src/NarratorHandoff.psm1') -Force
function Measure-Set([double[]]$Values){$sorted=@($Values|Sort-Object);[pscustomobject]@{count=$Values.Count;average=[math]::Round(($Values|Measure-Object -Average).Average,3);median=[math]::Round($(if($sorted.Count%2){$sorted[[math]::Floor($sorted.Count/2)]}else{($sorted[$sorted.Count/2-1]+$sorted[$sorted.Count/2])/2}),3);min=[math]::Round(($Values|Measure-Object -Minimum).Minimum,3);max=[math]::Round(($Values|Measure-Object -Maximum).Maximum,3)}}
$servicePath=Join-Path $root 'inference_service.json';Test-InferenceService $servicePath -ThrowOnFailure|Out-Null
$startupPath=Join-Path $root 'eval/.work/llama-server-state.json';$startup=if(Test-Path $startupPath){Get-Content -Raw $startupPath|ConvertFrom-Json}else{$null}
$state=New-GameState;Add-LocationState -State $state -Id study -VisibleObjects @('desk_01','fireplace_01','brass_key') -Exits @('hallway') -DisplayName 'Victorian study';Add-LocationState -State $state -Id hallway -Exits @('study') -DisplayName hallway;Add-ItemState -State $state -Id desk_01 -Location study -Owner $null -DisplayName 'writing desk' -Aliases @('desk','writing desk') -InteractableParts @('underneath');Add-ItemState -State $state -Id fireplace_01 -Location study -Owner $null -DisplayName fireplace -Aliases @('fireplace');Add-ItemState -State $state -Id brass_key -Location hook -Owner $null -DisplayName 'brass key' -Aliases @('key','brass key');$state.Player.Location='study';$state.Guillermo.Location='study';$context=New-InterpretationContext $state
$firstInterpreter=Invoke-IntentInterpretation 'Look beneath the desk.' $context -Seed 9500
$warmInterpreter=@();1..10|ForEach-Object{$warmInterpreter+=(Invoke-IntentInterpretation 'Look beneath the desk.' $context -Seed (9500+$_)).ElapsedSeconds}
$examples=@(Read-NarrationExemplars (Join-Path $root 'exemplars/narration_exemplars.json'))+@(Read-NarrationExemplars (Join-Path $root 'exemplars/grounding_retry_exemplars.json') -ExpectedCount 3)
$narratorCfg=Get-Content -Raw (Join-Path $root 'config.json')|ConvertFrom-Json;$narratorCfg.temperature=.15;$narratorCfg.max_tokens=224;$narratorCfg.stop_sequence="`nFACTS";$work=Join-Path $root 'eval/.work';$narratorCfgPath=Join-Path $work 'phase45_narrator_config.json';$narratorCfg|ConvertTo-Json|Set-Content -Encoding utf8 $narratorCfgPath
$case=[pscustomobject]@{location='study';time='midnight';weather='rain';actor='Armand';action_type='investigates';target='writing desk';degree='Success';facts=@('scratches are visible beneath the desk');visible=@('writing desk','fireplace','brass key on hook');forbidden_terms=@('murder')};$packet=ConvertTo-NarrationPacket $case;$prompt=Build-NarrationPrompt $packet facts $examples;$promptPath=Join-Path $work 'phase45_benchmark_narrator.txt';$prompt|Set-Content -NoNewline -Encoding utf8 $promptPath
$firstNarrator=Invoke-CommaGeneration $promptPath $narratorCfgPath -Seed 9600 -Temperature .15 -MaxTokens 224
$warmNarrator=@();1..10|ForEach-Object{$warmNarrator+=(Invoke-CommaGeneration $promptPath $narratorCfgPath -Seed (9600+$_) -Temperature .15 -MaxTokens 224).ElapsedSeconds}
$turns=@();1..5|ForEach-Object{$watch=[Diagnostics.Stopwatch]::StartNew();$interpretation=Invoke-IntentInterpretation 'Look beneath the desk.' $context -Seed (9700+$_);$engineIntent=ConvertTo-EngineIntent $interpretation.Intent;$engine=Resolve-StructuredIntent -State $state -Intent $engineIntent -Skill Investigation -DC 15 -FixedRoll 13 -PostActionState ([pscustomobject]@{desk_scratches_observed=$true}) -Events @('scratches are observed beneath the desk') -Visible @('writing desk','fireplace','brass key on hook');$ncase=Convert-HandoffToNarrationCase $engine.Handoff study midnight rain;$npacket=ConvertTo-NarrationPacket $ncase;$nprompt=Build-NarrationPrompt $npacket facts $examples;$npath=Join-Path $work "phase45_turn_$_.txt";$nprompt|Set-Content -NoNewline -Encoding utf8 $npath;$generation=Invoke-CommaGeneration $npath $narratorCfgPath -Seed (9800+$_) -Temperature .15 -MaxTokens 224;$text='You '+(($generation.Text-replace'(?s)\s*FACTS\s*$','').TrimStart());$validation=Test-NarrationOutput -Text $text -ForbiddenTerms @() -MaxWords 180 -Actor Armand;$watch.Stop();$turns+=[pscustomobject]@{elapsed_seconds=$watch.Elapsed.TotalSeconds;interpreter_seconds=$interpretation.ElapsedSeconds;narrator_seconds=$generation.ElapsedSeconds;validator_passed=$validation.Passed;raw_narration=$generation.Text}}
$result=[ordered]@{measured_utc=[datetime]::UtcNow.ToString('o');backend='llama-server';model='Comma Q4_K_M';service_startup_seconds=$(if($startup){$startup.startup_seconds}else{$null});first_interpreter_seconds=[math]::Round($firstInterpreter.ElapsedSeconds,3);warm_interpreter=Measure-Set $warmInterpreter;first_narrator_seconds=[math]::Round($firstNarrator.ElapsedSeconds,3);warm_narrator=Measure-Set $warmNarrator;warm_end_to_end=Measure-Set @($turns.elapsed_seconds);end_to_end_validator_passes=@($turns|Where-Object validator_passed).Count;end_to_end_turns=$turns;phase4_interpreter_baseline_seconds=3.20}
$result|ConvertTo-Json -Depth 12|Set-Content -Encoding utf8 (Join-Path $root 'eval/phase45_benchmark_results.json');$result|ConvertTo-Json -Depth 5
